import { HttpClient } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { map } from 'rxjs';
import { environment } from 'src/environments/environment';
import { EncryptionService } from '../core/encryption.service';

@Injectable({
  providedIn: 'root',
})
export class MyBookings {


  private API = `${environment.baseUrl}`;

  constructor(private http: HttpClient, private crypto: EncryptionService) { }

  getMyBookings(UserId: string | null) {
    return this.http.get(`${this.API}/getMyBookingsById/${UserId}`).pipe(
      map((res: any) => {
        const decrypted = this.crypto.decrypt(res.data);
        return {
          ...res,
          data: decrypted
        };
      })
    );
  }

downloadReceipt(bookingId: string | number, userId: string | null) {
  return this.http.get(
    `${this.API}/bookings/${userId}/${bookingId}/receipt`,
    { 
      responseType: 'blob',
      observe: 'response'
    }
  );
}

viewBookingDetails(bookingId: string | number){
  return this.http.get(
    `${this.API}/bookings/${bookingId}/receipt`,
    { 
      responseType: 'blob',
      observe: 'response'
    }
  );
}

submitTrekRating(
  bookingId: string | number,
  userId: string | null,
  payload: { rating: number; review?: string }
) {
  const encryptedPayload = this.crypto.encrypt(payload);
  return this.http
    .post(`${this.API}/bookings/${userId}/${bookingId}/rating`, {
      ...payload,
      encryptedPayload
    })
    .pipe(
      map((res: any) => {
        if (!res?.data) return res;
        try {
          const decrypted = this.crypto.decrypt(res.data);
          return { ...res, data: decrypted };
        } catch {
          return res;
        }
      })
    );
}
}
